-- DUMC v1.0.0: stable movie taxonomy and canonical movie metadata.
-- Additive only. Existing videos/categories remain unchanged.
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS dumc_folders (
 id TEXT PRIMARY KEY,
 parent_id TEXT REFERENCES dumc_folders(id) ON DELETE RESTRICT,
 name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100),
 description TEXT NOT NULL DEFAULT '',
 kind TEXT NOT NULL DEFAULT 'Folder',
 sort_order INTEGER NOT NULL DEFAULT 0,
 is_system INTEGER NOT NULL DEFAULT 0 CHECK(is_system IN (0,1)),
 owner_id TEXT REFERENCES users(id) ON DELETE RESTRICT,
 is_archived INTEGER NOT NULL DEFAULT 0 CHECK(is_archived IN (0,1)),
 created_at INTEGER NOT NULL,
 updated_at INTEGER NOT NULL,
 CHECK((is_system=1 AND owner_id IS NULL) OR (is_system=0 AND owner_id IS NOT NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_dumc_folder_scope_name
 ON dumc_folders(ifnull(parent_id,''),ifnull(owner_id,''),name COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS idx_dumc_folders_parent_order
 ON dumc_folders(parent_id,is_archived,sort_order,name);
CREATE INDEX IF NOT EXISTS idx_dumc_folders_owner
 ON dumc_folders(owner_id,is_archived);

CREATE TABLE IF NOT EXISTS dumc_movies (
 video_id TEXT PRIMARY KEY REFERENCES videos(id) ON DELETE CASCADE,
 original_language_folder_id TEXT REFERENCES dumc_folders(id) ON DELETE RESTRICT,
 industry_folder_id TEXT REFERENCES dumc_folders(id) ON DELETE RESTRICT,
 production_country_folder_id TEXT REFERENCES dumc_folders(id) ON DELETE RESTRICT,
 release_year INTEGER CHECK(release_year IS NULL OR release_year BETWEEN 1888 AND 2100),
 runtime_seconds INTEGER CHECK(runtime_seconds IS NULL OR runtime_seconds BETWEEN 1 AND 100000),
 metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json) AND json_type(metadata_json)='object'),
 created_at INTEGER NOT NULL,
 updated_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_dumc_movies_language ON dumc_movies(original_language_folder_id);
CREATE INDEX IF NOT EXISTS idx_dumc_movies_industry ON dumc_movies(industry_folder_id);
CREATE INDEX IF NOT EXISTS idx_dumc_movies_country_year ON dumc_movies(production_country_folder_id,release_year);

CREATE TABLE IF NOT EXISTS dumc_movie_folder_assignments (
 video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,
 folder_id TEXT NOT NULL REFERENCES dumc_folders(id) ON DELETE RESTRICT,
 relation_type TEXT NOT NULL CHECK(relation_type IN ('dubbed_language','genre','country','collection','subtitle_language','artwork','metadata')),
 created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
 created_at INTEGER NOT NULL,
 PRIMARY KEY(video_id,folder_id,relation_type)
);
CREATE INDEX IF NOT EXISTS idx_dumc_assignments_folder ON dumc_movie_folder_assignments(folder_id,relation_type,video_id);
CREATE INDEX IF NOT EXISTS idx_dumc_assignments_video ON dumc_movie_folder_assignments(video_id,relation_type);

CREATE TABLE IF NOT EXISTS dumc_audio_tracks (
 id TEXT PRIMARY KEY,
 video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,
 language_folder_id TEXT NOT NULL REFERENCES dumc_folders(id) ON DELETE RESTRICT,
 track_type TEXT NOT NULL CHECK(track_type IN ('original','dubbed')),
 label TEXT NOT NULL DEFAULT '',
 asset_key TEXT,
 source_url TEXT,
 is_default INTEGER NOT NULL DEFAULT 0 CHECK(is_default IN (0,1)),
 sort_order INTEGER NOT NULL DEFAULT 0,
 created_at INTEGER NOT NULL,
 updated_at INTEGER NOT NULL,
 CHECK((asset_key IS NOT NULL AND length(asset_key)>0) OR (source_url IS NOT NULL AND length(source_url)>0))
);
CREATE INDEX IF NOT EXISTS idx_dumc_audio_video ON dumc_audio_tracks(video_id,track_type,sort_order);
CREATE UNIQUE INDEX IF NOT EXISTS uq_dumc_audio_default
 ON dumc_audio_tracks(video_id,track_type) WHERE is_default=1;

CREATE TABLE IF NOT EXISTS dumc_subtitles (
 id TEXT PRIMARY KEY,
 video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,
 language_folder_id TEXT NOT NULL REFERENCES dumc_folders(id) ON DELETE RESTRICT,
 label TEXT NOT NULL DEFAULT '',
 asset_key TEXT,
 source_url TEXT,
 is_default INTEGER NOT NULL DEFAULT 0 CHECK(is_default IN (0,1)),
 created_at INTEGER NOT NULL,
 updated_at INTEGER NOT NULL,
 CHECK((asset_key IS NOT NULL AND length(asset_key)>0) OR (source_url IS NOT NULL AND length(source_url)>0))
);
CREATE INDEX IF NOT EXISTS idx_dumc_subtitles_video ON dumc_subtitles(video_id,language_folder_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_dumc_subtitle_default
 ON dumc_subtitles(video_id) WHERE is_default=1;

-- Seed the complete, versioned taxonomy. No media or existing category rows are modified.
